    def _verify_epoch(self, epoch: dict) -> tuple[bool, str]:
        """Verify a stored epoch's Merkle root against the chain records."""
        record_count = epoch.get("record_count", 0)
        if record_count > len(self._records):
            return False, (
                f"epoch claims {record_count} records but chain has "
                f"{len(self._records)}"
            )
        leaves = [
            _digest_bytes(r["chain_hash"])
            for r in self._records[:record_count]
        ]
        expected_root = "sha256:" + rfc9162_merkle_root(leaves).hex()
        stored_root = epoch.get("merkle_root", "")
        if stored_root != expected_root:
            return False, (
                f"merkle_root mismatch: stored {stored_root}, "
                f"computed {expected_root}"
            )
        # Validate sealed_at timestamp is after the last record's timestamp
        if record_count > 0:
            try:
                last_record_ts = self._records[record_count - 1]["sealed_body"]["timestamp_utc"]
                sealed_ts = epoch.get("sealed_at")
                if sealed_ts:
                    # Normalize both timestamps to UTC RFC3339 for comparison
                    last_norm = _normalize_timestamp(last_record_ts)
                    sealed_norm = _normalize_timestamp(sealed_ts)
                    if sealed_norm < last_norm:
                        return False, (
                            f"sealed_at {sealed_norm} is before last record's timestamp "
                            f"{last_norm}"
                        )
            except (KeyError, ValueError) as e:
                return False, f"timestamp validation failed: {e}"
        return True, "OK"
